WITH poor_quality_audio_devices AS (
    SELECT 
        audregistry
    FROM 
        audioandmedia
    WHERE 
        noiseisodb < 20
)

DELETE FROM audioandmedia
WHERE audregistry IN (
    SELECT audregistry FROM poor_quality_audio_devices
);

SELECT * FROM audioandmedia;

